css:
body :where([data-bz-node="mc"]) .bz-block{padding:0}
body :where([data-bz-node="mc"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="mc"]>.bz-container{padding-inline:0}

body [data-bz-node="mc"]{background:#fff;padding:90px 0}
body [data-bz-node="mc"]>.bz-container{max-width:var(--container)}
body [data-bz-node="mc-row"]{display:grid;grid-template-columns:1fr 1fr;gap:0 56px;align-items:center}
body [data-bz-node="mc-row"]>.bz-col{grid-column:auto}
body [data-bz-node="mc-map"] .bz-widget__h,body [data-bz-node="mc-map"] .bz-loclist,body [data-bz-node="mc-map"] .bz-widget__empty{display:none}
body [data-bz-node="mc-map"] .bz-map{aspect-ratio:4/3;border-radius:0;margin:0;border:1px solid #e4e4e2}
body [data-bz-node="mc-intro"] .bz-text{max-width:none}
body [data-bz-node="mc-intro"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0;margin:0 0 14px}
body [data-bz-node="mc-lines"]{display:block;margin-top:24px}
body [data-bz-node^="mc-line-"]{display:block;margin-bottom:14px}
body [data-bz-node^="mc-line-"] .bz-text{max-width:none}
body [data-bz-node^="mc-line-"] p{position:relative;padding-left:32px;font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0}
body [data-bz-node^="mc-line-"] p::before{content:"";position:absolute;left:0;top:3px;width:18px;height:18px;background:var(--accent);-webkit-mask:url(/icons/phone.svg) center/18px no-repeat;mask:url(/icons/phone.svg) center/18px no-repeat}
body [data-bz-node$="-1"][data-bz-node^="mc-line-"] p::before{-webkit-mask-image:url(/icons/map-pin.svg);mask-image:url(/icons/map-pin.svg)}
body [data-bz-node^="mc-line-"] a{color:inherit;text-decoration:none}
body [data-bz-node^="mc-line-"] a:hover{color:var(--accent)}
@media (max-width:1100px){body [data-bz-node="mc"]{padding:64px 24px}body [data-bz-node="mc-row"]{grid-template-columns:1fr;gap:32px}}
@media (max-width:640px){body [data-bz-node="mc"]{padding:48px 20px}}
